#include <fstream>
#include <iostream>
#include <vector>
using namespace std;

struct Equipe {
    int points;
    int buts;
};

int main() {
    int n;
    cin >> n;
    vector<Equipe> equipes;
    for (int i = 0; i < n; i++) {
        Equipe e;
        cin >> e.points >> e.buts;
        equipes.push_back(e);
    }

    ofstream sortie("tournoi.bin", ios::out | ios::binary);
    size_t combien = equipes.size();
    sortie.write(reinterpret_cast<const char*>(&combien), sizeof(combien));
    for (const Equipe& e : equipes) {
        sortie.write(reinterpret_cast<const char*>(&e), sizeof(e));
    }
    sortie.close();

    ifstream entree("tournoi.bin", ios::in | ios::binary);
    size_t m;
    entree.read(reinterpret_cast<char*>(&m), sizeof(m));
    int totalPoints = 0;
    int totalButs = 0;
    for (size_t i = 0; i < m; i++) {
        Equipe e;
        entree.read(reinterpret_cast<char*>(&e), sizeof(e));
        totalPoints += e.points;
        totalButs += e.buts;
    }
    entree.close();

    cout << "equipes = " << m << "\n";
    cout << "total points = " << totalPoints << "\n";
    cout << "total buts = " << totalButs << "\n";
    return 0;
}

